<template>
<view class="page" :class="theme"><view class="heading" v-html="homeTitle"></view><text class="hint">{{ user?user.name+' · '+roleName:'把每一件学生工作，安排得井井有条。' }}</text>
<view v-if="error" class="error" role="alert">{{ error }}</view>
<view v-if="!user" class="card"><view class="title">{{ activation?'激活账号':'登录工作台' }}</view><input v-if="activation" v-model="login.token" placeholder="管理员提供的一次性邀请凭据"/><input v-else v-model="login.username" placeholder="管理员分配的账号"/><input v-model="login.password" password placeholder="密码（激活时至少 12 位字母和数字）"/><button class="primary" :disabled="busy" @click="signIn">{{ activation?'激活账号':'登录' }}</button><button @click="activation=!activation">{{ activation?'返回登录':'使用邀请激活' }}</button><view class="hint">无需短信验证码，账号由学校管理员统一管理。</view><input v-model="server" placeholder="学校 HTTPS 服务地址，以 /api 结尾"/><button @click="configure">保存学校服务地址</button></view>
<view v-else-if="user.mustChangePassword" class="card"><view class="title">首次登录请修改密码</view><input v-model="password.old" password placeholder="当前临时密码"/><input v-model="password.next" password placeholder="新密码，至少 12 位，含字母和数字"/><input v-model="password.repeat" password placeholder="再次输入新密码"/><button class="primary" :disabled="busy" @click="changePassword">保存新密码</button><button @click="logout">退出</button></view>
<template v-else><view class="mobile-navigation"><view class="nav primary-nav"><button v-for="n in primaryNavigation" :key="n.id" :class="page===n.id?'primary':''" @click="go(n.id)">{{ n.title }}<text v-if="n.id==='chat'&&chatUnread" class="chat-count">{{ chatUnread>99?'99+':chatUnread }}</text></button></view><view v-if="businessNavigation.length && page!=='chat'" class="business-navigation"><text class="hint">事务办理</text><view class="nav"><button v-for="n in businessNavigation" :key="n.id" :class="page===n.id?'primary':''" @click="go(n.id)">{{ n.title }}</button></view></view></view><button v-if="page!=='chat'" :disabled="busy||chatBusy" @click="refresh">{{ busy?'正在处理…':'刷新当前页面' }}</button>
<MobileChat v-if="page==='chat'&&!user.roleRestricted" :key="user.id+':'+(user.activeRoleId||'primary')" :user="user" :refresh-key="chatRefresh" @unread-change="chatUnread=$event" @busy-change="chatBusy=$event"/>
<template v-if="page==='ai'"><view class="card ai-card"><view class="title">AI 办公助手</view><view class="hint">生成可编辑草稿，内容不会自动发布或替代审批。请勿输入学生身份证号、健康信息或谈话原文。</view><picker :range="aiScenarios" range-key="label" @change="aiForm.scenario=aiScenarios[Number(($event as any).detail.value)].id"><view class="field">{{ aiScenarios.find(s=>s.id===aiForm.scenario)?.label }}</view></picker><input v-model="aiForm.topic" placeholder="主题，例如：国庆假期安全提醒"/><textarea v-model="aiForm.details" placeholder="补充要点、办理要求或工作事实（可选）"/><input v-if="aiForm.scenario==='notice'" v-model="aiForm.audience" placeholder="接收对象，例如：2025级智能制造1班"/><input v-if="['notice','task'].includes(aiForm.scenario)" v-model="aiForm.deadline" placeholder="截止时间（可选）"/><picker :range="aiTones" range-key="label" @change="aiForm.tone=aiTones[Number(($event as any).detail.value)].id"><view class="field">语气：{{ aiTones.find(t=>t.id===aiForm.tone)?.label }}</view></picker><button class="primary" :loading="aiBusy" :disabled="aiBusy||(!aiForm.topic.trim()&&!aiForm.details.trim())" @click="generateAi">{{ aiBusy?'正在生成…':'生成草稿' }}</button></view><view v-if="aiResult" class="card"><view class="title">{{ aiResult.title }}</view><view class="body">{{ aiResult.content }}</view><view class="hint">{{ aiResult.warning || '请核对事实、对象和截止时间后再使用。' }}</view><button @click="copyAiResult">复制草稿</button></view></template>
<template v-if="page==='board'"><view class="title">我的待办</view><view v-for="item in list" :key="item.id" class="card"><view class="title">{{ item.title }}</view><text class="tag">{{ status(item.status) }}</text><view class="hint">{{ fmt(item.dueAt) }} · {{ item.nextAction }}</view><button @click="openSource(item)">进入办理</button></view></template>
<template v-if="page==='notices'"><view v-for="item in list" :key="item.id" class="card"><view class="title">{{ item.title }}</view><text class="tag">{{ status(item.status) }}</text><view class="hint">截止：{{ fmt(item.dueAt) }}</view><button @click="readNotice(item)">查看公告</button><template v-if="selected?.id===item.id"><view class="body">{{ item.content }}</view><view class="hint">阅读与业务完成分别记录。</view><button v-if="student && item.requiresConfirmation" class="primary" :disabled="busy" @click="act('/notices/'+item.id+'/confirm',{version:item.version})">确认已知晓</button><button v-if="item.linkedId" @click="openSource({source:item.linkedKind,sourceId:item.linkedId})">办理关联事项</button></template></view></template>
<template v-if="page==='collections'"><view v-for="item in list" :key="item.id" class="card"><view class="title">{{ item.name }}</view><view class="hint">{{ status(item.status) }} · {{ fmt(item.dueAt) }}</view><button @click="openCollection(item)">查看填报任务</button></view><view v-if="selected" class="card"><view class="title">{{ selected.name }}</view><view class="body">{{ selected.purpose }}</view><template v-if="student"><view v-for="f in selected.fields" :key="f.key"><text class="label">{{ f.label }}{{ f.required?' *':'' }}</text><picker v-if="['select','radio'].includes(f.type)" :range="f.options" @change="values[f.key]=f.options[Number(($event as any).detail.value)]"><view class="card">{{ values[f.key]||'请选择' }}</view></picker><checkbox-group v-else-if="f.type==='multi'" @change="values[f.key]=($event as any).detail.value"><label v-for="v in f.options" :key="v"><checkbox :value="v" :checked="(values[f.key]||[]).includes(v)"/>{{ v }}</label></checkbox-group><MobileMaterials v-else-if="f.type==='attachment'" :model-value="values[f.key]||[]" @update:model-value="values[f.key]=$event" @busy="uploading=$event"/><textarea v-else-if="f.type==='textarea'" v-model="values[f.key]" :placeholder="f.label"/><input v-else v-model="values[f.key]" :type="f.type==='number'?'digit':'text'" :placeholder="f.type==='date'?'YYYY-MM-DD':f.label"/></view><view class="hint">{{ selected.myAnswer?.reviewReason }} {{ selected.myAnswer?.receipt }}</view><view class="row"><button :disabled="busy||uploading" @click="saveCollection(false)">保存草稿</button><button class="primary" :disabled="busy||uploading" @click="saveCollection(true)">正式提交</button></view></template><template v-else><view v-for="answer in (selected.roster||[]).filter((r:any)=>r.canReview).map((r:any)=>r.answer)" :key="answer.id" class="card"><text>{{ answer.studentId }} · {{ status(answer.status) }}</text><view v-for="f in selected.fields" :key="f.key" class="body">{{ f.label }}：{{ answer.values?.[f.key] }}</view><view v-if="answer.status==='pending_review'" class="row"><button @click="reviewAnswer(answer,true)">通过</button><button @click="reviewAnswer(answer,false)">退回补正</button></view></view></template></view></template>
<template v-if="page==='requests'"><button v-if="student" class="primary" @click="newRequest">新建申请 / 咨询</button><view v-if="editing" class="card"><picker :range="requestTypes" range-key="title" @change="requestForm.type=requestTypes[Number(($event as any).detail.value)].id"><view class="card">{{ requestTypes.find(t=>t.id===requestForm.type)?.title }}</view></picker><input v-model="requestForm.title" placeholder="事项标题"/><textarea v-model="requestForm.content" placeholder="请说明事由和需要协助的内容"/><template v-if="requestForm.type==='leave'"><picker :range="leaveTypes" range-key="title" @change="requestForm.leaveType=leaveTypes[Number(($event as any).detail.value)].id"><view class="card">{{ leaveTypes.find(t=>t.id===requestForm.leaveType)?.title }}</view></picker><view>是否离校 <switch :checked="requestForm.offCampus" @change="requestForm.offCampus=($event as any).detail.value"/></view><input v-if="requestForm.offCampus" v-model="requestForm.contact" placeholder="离校联系方式"/><input v-model="requestForm.destination" placeholder="去向"/><input v-model="requestForm.startAt" placeholder="开始时间，如 2026-10-01 08:00"/><input v-model="requestForm.endAt" placeholder="结束时间，如 2026-10-02 18:00"/><textarea v-model="requestForm.emergencyReason" placeholder="应急事后补录须说明原发生时间、线下办理人和依据"/><view v-if="requestForm.originalId" class="hint">关联原单 {{ requestForm.originalId }} · {{ requestForm.leaveOperation==='extend'?'续假待批不延长原期限':requestForm.leaveOperation==='cancel'?'待确认前原安排继续有效':'变更批准后替代原安排' }}</view></template><MobileMaterials v-model="requestForm.attachmentIds" @busy="uploading=$event"/><button :disabled="busy||uploading" class="primary" @click="submitRequest">提交申请</button><button @click="editing=false">取消编辑</button></view><view v-for="item in list" :key="item.id" class="card"><view class="title">{{ item.title }}</view><text class="tag">{{ status(item.status) }}</text><view class="hint">{{ item.userName }} · {{ item.id }}</view><view class="body">{{ item.content }}</view><view class="hint">{{ item.comment }} {{ item.exceptionReason }}</view><view v-if="item.type==='leave'" class="hint">{{ fmt(item.startAt) }} 至 {{ fmt(item.endAt) }}<view v-for="node in item.approvalNodes||[]" :key="node.approverId+node.name">{{ node.name||node.approverId }}：{{ status(node.status) }}</view></view><template v-if="student"><button v-if="item.status==='returned'" @click="editRequest(item)">补正重提</button><button v-if="['pending','returned','exception'].includes(item.status)" @click="requestAction(item,'cancel')">撤销申请</button><button v-if="item.type==='leave'&&item.status==='exception'" @click="act('/office/leaves/'+item.id+'/rematch',{})">规则已配置后重新匹配</button><template v-if="item.type==='leave'&&item.status==='approved'&&item.fulfilment!=='closed'"><view class="hint">履行状态：{{ item.fulfilment==='return_pending'?'待老师核验销假':'未销假' }}；原有效结束 {{ fmt(item.endAt) }}</view><button v-if="item.fulfilment!=='return_pending'" class="primary" @click="requestAction(item,'return_submit')">登记实际返校 / 销假</button><view class="row"><button @click="relatedRequest(item,'extend')">申请续假</button><button @click="relatedRequest(item,'change')">申请变更</button><button v-if="new Date(item.startAt).getTime()>Date.now()" @click="relatedRequest(item,'cancel')">申请取消批准安排</button></view></template></template><template v-else><view v-if="item.status==='pending'&&(item.type!=='leave'||(item.approvalNodes||[]).some((n:any)=>n.status==='pending'&&n.approverId===user.id))" class="row"><button @click="requestAction(item,'approve')">审批通过</button><button @click="requestAction(item,'return')">退回补正</button><button @click="requestAction(item,'reject')">驳回</button></view><view v-if="item.type==='leave'&&item.fulfilment==='return_pending'" class="row"><button @click="requestAction(item,'return_approve')">核实销假</button><button @click="requestAction(item,'return_reject')">退回销假更正</button></view><button v-if="item.type!=='leave'&&item.status==='approved'" @click="requestAction(item,'close')">办结</button></template></view></template>
<template v-if="page==='holidays'"><view v-for="item in list" :key="item.id" class="card"><view class="title">{{ item.title }}</view><view class="hint">{{ fmt(item.startAt) }} 至 {{ fmt(item.endAt) }}</view><template v-if="student"><input v-model="holidayFor(item).destination" placeholder="假期去向"/><input v-model="holidayFor(item).contact" placeholder="紧急联系方式"/><input v-model="holidayFor(item).returnAt" placeholder="预计返校时间，如 2026-10-07 18:00"/><button v-if="item.destinationEnabled!==false&&!item.myRegistration?.destinationExempt" :disabled="busy||item.status==='closed'" @click="registerHoliday(item)">保存去向登记</button><button v-if="item.returnEnabled!==false&&!item.myRegistration?.returnExempt&&!item.myRegistration?.returnedAt" :disabled="busy||item.status==='closed'" @click="act('/holidays/'+item.id+'/return',{})">本人已返校，提交核验</button><view class="hint">{{ item.myRegistration?.destinationExempt?'去向已豁免':'' }} {{ item.myRegistration?.verifiedAt?'返校已核验':'' }}</view></template><template v-else><view v-for="r in item.registrations||[]" :key="r.userId" class="card"><text>{{ r.userName }} · {{ r.verifiedAt?'已核验':r.returnedAt?'待核验':'未返校' }}</text><button v-if="r.returnedAt&&!r.verifiedAt" @click="act('/holidays/'+item.id+'/verify',{userId:r.userId,comment:'现场核实返校'})">核实返校</button></view></template></view></template>
<template v-if="page==='worklogs'"><view class="card"><view class="title">登记工作与跟进</view><picker :range="logTypes" range-key="title" @change="log.type=logTypes[Number(($event as any).detail.value)].id"><view class="card">{{ logTypes.find(t=>t.id===log.type)?.title }}</view></picker><input v-model="log.title" placeholder="工作标题"/><textarea v-model="log.content" placeholder="工作内容，按授权范围保密"/><input v-model="log.studentId" placeholder="关联学生编号（可选）"/><input v-model="log.followUpAt" placeholder="下次跟进时间（可选）"/><MobileMaterials v-model="log.attachmentIds" @busy="uploading=$event"/><button class="primary" :disabled="busy||uploading" @click="saveLog">保存工作记录</button></view><view v-for="item in list" :key="item.id" class="card"><view class="title">{{ item.title }}</view><view class="body">{{ item.content }}</view><view class="hint">跟进：{{ fmt(item.followUpAt) }}</view></view></template>
<template v-if="page==='messages'"><view v-for="item in list" :key="item.id" class="card"><view class="title">{{ item.title }}</view><view class="body">{{ item.content||item.message }}</view><text class="hint">{{ item.resolved?'已处理':'待处理' }}</text></view></template>
<MobileServices v-if="page==='services'" :refresh-key="servicesRefresh" :user="user" @open-settings="go('settings')"/><template v-if="page==='settings'"><view v-if="roleOptions.length>1" class="card"><view class="title">办公角色</view><view class="hint">经管理员复核后可切换；当前只使用一种角色权限。</view><button v-for="r in roleOptions" :key="r.id" :disabled="busy||uploading||r.id===(user.activeRoleId||'primary')" @click="switchRole(r.id)">{{ roleLabels[r.role]||r.role }} · {{ r.college||r.className||'已授权范围' }}{{ r.id===(user.activeRoleId||'primary')?'（当前）':'' }}</button></view><view class="card"><view class="title">外观主题</view><view class="row"><button v-for="t in themes" :key="t.id" @click="saveTheme(t.id)">{{ t.title }}</button></view><text class="hint">当前版本 {{ CLIENT_VERSION }} · 主题会同步到同一账号的其他设备。</text><view class="title">修改密码</view><input v-model="password.old" password placeholder="当前密码"/><input v-model="password.next" password placeholder="至少 12 位，含字母和数字"/><input v-model="password.repeat" password placeholder="再次输入新密码"/><button @click="changePassword">修改密码并重新登录</button><button @click="logout">退出登录</button></view></template>
<view v-if="!list.length&&!busy&&!['settings','worklogs','services','ai','chat'].includes(page)" class="empty">当前没有待显示的事项。</view></template></view>
</template>
<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,reactive,ref} from 'vue';import {onShow,onHide} from '@dcloudio/uni-app';import {api,getToken,setToken,saveBase} from '../../platform';import {CLIENT_VERSION,passwordValid,statusNames} from '../../../../shared/domain';import MobileMaterials from '../../components/MobileMaterials.vue';import MobileServices from '../../components/MobileServices.vue';import MobileChat from '../../components/MobileChat.vue';
const chatUnread=ref(0),chatBusy=ref(false),chatRefresh=ref(0);
const roleOptions=ref<any[]>([]);const roleLabels:Record<string,string>={admin:'超级管理员',counselor:'辅导员',student:'学生',leader:'学院负责人',business:'业务经办',finance:'财务经办',logistics:'后勤经办',mentor:'导师',assistant:'学生助理',sysadmin:'系统管理员'};
async function switchRole(id:string){if(busy.value||uploading.value||chatBusy.value)return;const consent=await new Promise<boolean>(resolve=>uni.showModal({title:'切换办公角色',content:'请先保存草稿。切换将清除本页未保存内容，并使当前账号其他旧登录会话失效。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!consent)return;await run(async()=>{const data=await api('/auth/switch-role','POST',{roleId:id});reset();await nextTick();setToken(data.token);user.value=data.user;page.value=data.user.roleRestricted?'services':'board';await load();});}
const user=ref<any>(null),busy=ref(false),uploading=ref(false),error=ref(''),page=ref('board'),list=ref<any[]>([]),selected=ref<any>(null),editing=ref(false),activation=ref(false),server=ref(String(uni.getStorageSync('school_api_url')||''));const login=reactive({username:'',password:'',token:''}),password=reactive({old:'',next:'',repeat:''}),values=reactive<Record<string,any>>({}),holiday=reactive({destination:'',contact:'',returnAt:''});const requestForm=reactive<any>({}),log=reactive<any>({type:'talk',title:'',content:'',studentId:'',followUpAt:'',attachmentIds:[]});
const student=computed(()=>user.value?.role==='student'),staff=computed(()=>['admin','counselor'].includes(user.value?.role)),theme=computed(()=>user.value?.theme||'blue'),roleName=computed(()=>({admin:'超级管理员',counselor:'辅导员',student:'学生',leader:'学院负责人',business:'业务经办',finance:'财务经办',logistics:'后勤经办',mentor:'导师',assistant:'学生助理',sysadmin:'系统管理员'} as any)[user.value?.role]||'学校用户');
const leaveTypes=[{id:'personal',title:'事假'},{id:'sick',title:'病假'},{id:'official',title:'公假'},{id:'other',title:'其他'}];const themes=[{id:'blue',title:'晴空蓝'},{id:'green',title:'竹叶绿'},{id:'pink',title:'蔷薇粉'}],requestTypes=[{id:'consultation',title:'咨询求助'},{id:'leave',title:'请假申请'},{id:'material',title:'材料补充'},{id:'aid',title:'资助咨询'}],logTypes=[{id:'talk',title:'谈心谈话'},{id:'dormitory',title:'下宿舍'},{id:'class_visit',title:'下课堂'},{id:'family',title:'家校联系'},{id:'education',title:'思政活动'}];
const navigation=computed(()=>[{id:'board',title:'待办'},{id:'chat',title:'聊天'},{id:'notices',title:'公告'},{id:'collections',title:'材料填报'},...((student.value||staff.value)?[{id:'requests',title:'申请办理'},{id:'holidays',title:'假期登记'}]:[]),...(staff.value?[{id:'worklogs',title:'工作记录'},{id:'ai',title:'AI助手'}]:[]),{id:'messages',title:'提醒'},{id:'services',title:'业务服务'},{id:'settings',title:'我的'}].filter(n=>!user.value?.roleRestricted||['services','settings'].includes(n.id)));
/* 角色区分：管理员以治理/业务服务为主，辅导员以学生材料办理为主，其余角色回到个人事项。底部主入口固定 4 个，按角色替换首屏第 4 项。 */
const managerRole=computed(()=>['admin','sysadmin','leader'].includes(user.value?.role||''));
const homeTitle=computed(()=>managerRole.value?'智能工程技术学院<br/>管理系统工作台':staff.value?'智能工程技术学院<br/>辅导员学工工作台':'智能工程技术学院<br/>学工服务台');
const primaryIds=computed(()=>{
  if(user.value?.roleRestricted)return ['board','chat','notices','services','settings'];
  return managerRole.value?['board','chat','notices','services','settings']:staff.value?['board','chat','notices','collections','settings']:['board','chat','notices','settings'];
});
const primaryNavigation=computed(()=>navigation.value.filter(n=>primaryIds.value.includes(n.id)));
const businessNavigation=computed(()=>navigation.value.filter(n=>!primaryNavigation.value.some(p=>p.id===n.id)));
const aiScenarios=[{id:'notice',label:'公告草稿'},{id:'task',label:'任务拆解'},{id:'worklog',label:'工作记录整理'},{id:'summary',label:'周报摘要'}];const aiTones=[{id:'formal',label:'正式清晰'},{id:'warm',label:'温和提醒'},{id:'concise',label:'简洁直接'}];const aiForm=reactive<any>({scenario:'notice',topic:'',details:'',audience:'',deadline:'',tone:'formal'});const aiResult=ref<any>(null),aiBusy=ref(false);
const status=(v:string)=>statusNames[v]||v;const fmt=(v?:string)=>v?new Date(v).toLocaleString('zh-CN'):'未设置';function iso(v:string){if(!v)return '';const date=new Date(v.replace(' ','T'));if(isNaN(date.getTime()))throw new Error('时间格式无效，请填写 YYYY-MM-DD HH:mm。');return date.toISOString();}
async function run(fn:()=>Promise<void>){while(busy.value)await new Promise(resolve=>setTimeout(resolve,25));busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message||'操作未完成，请重试。';}finally{busy.value=false;}}
function reset(){user.value=null;list.value=[];selected.value=null;editing.value=false;roleOptions.value=[];page.value='board';uploading.value=false;chatUnread.value=0;chatBusy.value=false;Object.assign(password,{old:'',next:'',repeat:''});login.password='';login.token='';Object.keys(values).forEach(k=>delete values[k]);Object.keys(requestForm).forEach(k=>delete requestForm[k]);Object.assign(log,{title:'',content:'',studentId:'',followUpAt:'',attachmentIds:[]});Object.keys(holidayForms).forEach(k=>delete holidayForms[k]);setToken('');}function expired(){reset();error.value='登录已失效，请重新登录。';}
async function signIn(){await run(async()=>{if(activation.value){if(!passwordValid(login.password))throw new Error('密码至少 12 位，包含字母与数字。');await api('/auth/activate','POST',{token:login.token,password:login.password});activation.value=false;login.token='';login.password='';uni.showToast({title:'已激活，请登录',icon:'none'});return;}const data=await api('/auth/login','POST',{username:login.username,password:login.password});setToken(data.token);user.value=data.user;login.password='';await load();});}
async function logout(){
  if(chatBusy.value){const confirmed=await new Promise<boolean>(resolve=>uni.showModal({title:'确认退出',content:'退出会丢弃未发送的聊天草稿。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!confirmed)return;}
  const revocation=api('/auth/logout','POST');reset();
  try{await revocation;}catch(e:any){if(!getToken()&&e.code!=='SESSION_CHANGED'&&e.status!==401)error.value='已退出本机。服务器未确认注销，请在网络恢复后撤销旧登录设备。';}
}function configure(){try{saveBase(server.value);reset();uni.showToast({title:'服务地址已保存',icon:'none'});}catch(e){error.value=(e as Error).message;}}
async function changePassword(){await run(async()=>{if(!passwordValid(password.next)||password.next!==password.repeat)throw new Error('请检查密码强度及两次输入是否一致。');await api('/auth/password','POST',{oldPassword:password.old,newPassword:password.next});Object.assign(password,{old:'',next:'',repeat:''});reset();uni.showToast({title:'密码已改，请重新登录',icon:'none'});});}
async function load(){if(!user.value||user.value.mustChangePassword)return;const token=getToken();if(user.value.roleRestricted&&!['services','settings'].includes(page.value))page.value='services';if(page.value==='settings'){const roles=await api('/auth/roles');if(getToken()===token)roleOptions.value=roles.roles;list.value=[];return;}const routes:any={board:'/office/board',notices:'/notices',collections:'/collections',requests:'/requests',holidays:'/holidays',worklogs:'/worklogs',messages:'/messages'};if(!routes[page.value]){list.value=[];return;}const result=await api(routes[page.value]);if(getToken()!==token)return;list.value=Array.isArray(result)?result:result.items||result.tasks||[];if(page.value==='holidays')list.value.forEach(item=>item.myRegistration=(item.registrations||[]).find((r:any)=>r.userId===user.value.id));}
async function generateAi(){if(aiBusy.value||(!aiForm.topic.trim()&&!aiForm.details.trim()))return;aiBusy.value=true;error.value='';try{aiResult.value=await api('/ai/assist','POST',{...aiForm,topic:aiForm.topic.trim(),details:aiForm.details.trim(),audience:aiForm.audience.trim(),deadline:aiForm.deadline.trim()});}catch(e){error.value=(e as Error).message||'AI 草稿生成失败，请稍后重试。';}finally{aiBusy.value=false;}}
function copyAiResult(){if(!aiResult.value)return;uni.setClipboardData({data:`${aiResult.value.title}\n\n${aiResult.value.content}`,success:()=>uni.showToast({title:'已复制草稿',icon:'none'})});}
const servicesRefresh=ref(0);async function restoreIdentity(){const token=getToken();const current=await api('/auth/me');if(getToken()!==token)return false;user.value=current;return true;}async function refresh(){await run(async()=>{if(!await restoreIdentity())return;if(page.value==='services')servicesRefresh.value++;if(page.value==='chat')chatRefresh.value++;await load();refreshChatUnread();});}function go(id:string){if(busy.value)return;if((chatBusy.value&&id!==page.value)||uploading.value){uni.showToast({title:'请先完成或取消文件上传和消息发送',icon:'none'});return;}page.value=id;selected.value=null;editing.value=false;list.value=[];refresh();}function openSource(item:any){const map:any={notice:'notices',collection:'collections',request:'requests',leave:'requests',holiday:'holidays',worklog:'worklogs',care:'worklogs',manual:'board'};const target=map[item.source];if(target&&target!=='board')go(target);else if(item.route==='operations'||['cooperation','activity','award','housing','support'].includes(item.source))go('services');else error.value='该事项请在电脑端业务协同页面办理，事项编号：'+(item.sourceId||item.id);}
async function act(path:string,body:any){await run(async()=>{await api(path,'POST',body);await load();uni.showToast({title:'已保存',icon:'none'});});}async function readNotice(item:any){await run(async()=>{if(student.value)await api('/notices/'+item.id+'/read','POST');selected.value=item;});}
async function openCollection(item:any){await run(async()=>{selected.value=await api('/collections/'+item.id);Object.keys(values).forEach(k=>delete values[k]);selected.value.myAnswer=selected.value.roster?.find((r:any)=>r.studentId===user.value.id)?.answer;for(const [key,entry] of Object.entries(selected.value.prefill||{}))values[key]=(entry as any).value;Object.assign(values,selected.value.myAnswer?.values||{});});}
async function saveCollection(submit:boolean){await run(async()=>{const answer=await api('/collections/'+selected.value.id+'/answer','PUT',{values:{...values},version:selected.value.myAnswer?.version,submit});selected.value.myAnswer=answer;uni.showToast({title:submit?'提交成功':'草稿已保存',icon:'none'});});}
async function reason(title:string){return new Promise<string>((resolve,reject)=>uni.showModal({title,editable:true,placeholderText:'填写办理说明 / 依据',success:r=>r.confirm&&r.content?.trim()?resolve(r.content.trim()):reject(new Error('操作未提交，请填写说明。')),fail:reject}));}
async function reviewAnswer(answer:any,approved:boolean){await run(async()=>{const note=await reason(approved?'审核通过':'退回补正');await api('/collections/'+selected.value.id+'/answers/'+answer.studentId+'/review','POST',{approved,reason:note});selected.value=await api('/collections/'+selected.value.id);});}
function newRequest(){Object.keys(requestForm).forEach(k=>delete requestForm[k]);Object.assign(requestForm,{type:'consultation',title:'',content:'',startAt:'',endAt:'',leaveType:'personal',offCampus:false,destination:'',contact:'',emergencyReason:'',leaveOperation:'new',attachmentIds:[]});editing.value=true;}function editRequest(item:any){Object.keys(requestForm).forEach(k=>delete requestForm[k]);Object.assign(requestForm,item);editing.value=true;}function relatedRequest(item:any,operation:string){Object.keys(requestForm).forEach(k=>delete requestForm[k]);Object.assign(requestForm,item,{originalId:item.id,leaveOperation:operation,emergencyReason:'',attachmentIds:[...(item.attachmentIds||[])]});delete requestForm.id;editing.value=true;}
async function submitRequest(){await run(async()=>{const body={...requestForm,startAt:iso(requestForm.startAt||''),endAt:iso(requestForm.endAt||'')};await api(requestForm.id?'/requests/'+requestForm.id:'/requests',requestForm.id?'PUT':'POST',body);editing.value=false;await load();});}async function requestAction(item:any,action:string){await run(async()=>{const comment=await reason('确认办理');let actualReturnAt:string|undefined;if(action==='return_submit')actualReturnAt=iso(await reason('请填写实际返校时间，如 2026-10-01 18:00'));await api('/requests/'+item.id+'/action','POST',{action,comment,version:item.version,actualReturnAt});await load();});}
const holidayForms=reactive<Record<string,any>>({});function holidayFor(item:any){if(!holidayForms[item.id])holidayForms[item.id]={destination:item.myRegistration?.destination||'',contact:item.myRegistration?.contact||'',returnAt:item.myRegistration?.returnAt||item.endAt};return holidayForms[item.id];}
async function registerHoliday(item:any){await run(async()=>{const form=holidayFor(item);await api('/holidays/'+item.id+'/register','POST',{...form,returnAt:iso(form.returnAt)});await load();});}async function saveLog(){await run(async()=>{await api('/worklogs','POST',{...log,followUpAt:iso(log.followUpAt)});Object.assign(log,{title:'',content:'',studentId:'',followUpAt:'',attachmentIds:[]});await load();});}async function saveTheme(value:string){await run(async()=>{user.value=await api('/auth/theme','PUT',{theme:value});});}
let chatTimer:ReturnType<typeof setInterval>|undefined,chatChecking=false,foreground=true;
async function refreshChatUnread(){if(!foreground||!user.value||user.value.mustChangePassword||user.value.roleRestricted||chatChecking)return;const token=getToken();chatChecking=true;try{const result=await api('/chat/unread');if(token===getToken())chatUnread.value=result.unreadCount;}catch{/* 聊天页显示可重试错误。 */}finally{chatChecking=false;}}
function startChatTimer(){if(!chatTimer)chatTimer=setInterval(refreshChatUnread,10000);refreshChatUnread();}
function stopChatTimer(){if(chatTimer)clearInterval(chatTimer);chatTimer=undefined;}
onMounted(()=>{uni.$on('session-expired',expired);startChatTimer();if(getToken())run(async()=>{if(await restoreIdentity()){await load();refreshChatUnread();}});});onShow(()=>{foreground=true;startChatTimer();if(user.value&&!busy.value)run(async()=>{if(await restoreIdentity())await load();});});onHide(()=>{foreground=false;stopChatTimer();});onBeforeUnmount(()=>{stopChatTimer();uni.$off('session-expired',expired);});
</script>
<style scoped>
.mobile-navigation{margin:18px 0}.primary-nav{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px}.primary-nav button{min-width:0;margin:0;padding:0 5px;font-size:14px}.business-navigation{margin-top:12px;border-top:1px solid #dce3ed;padding-top:10px}.business-navigation .nav{margin:6px 0}.chat-count{display:inline-block;background:#be3a49;color:white;border-radius:10px;font-size:10px;line-height:16px;padding:0 4px;margin-left:3px}
</style>
